from collections import Counter
import sys
sys.setrecursionlimit(10000)

def components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                col=grid[i][j]; st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and grid[x][y]==col:
                            seen[x][y]=True; st.append((x,y))
                comps.append(comp)
    return comps

def f(inp):
    grid=[r[:] for r in inp]; h,w=len(grid),len(grid[0])
    bg=max(set(c for r in grid for c in r), key=lambda c: sum(r.count(c) for r in grid))
    comps=components(grid,bg)
    out=[r[:] for r in grid]
    for comp in comps:
        cnt=Counter(grid[a][b] for a,b in comp); dom,_=cnt.most_common(1)[0]
        extra=[c for c in cnt if c!=dom]
        # majority -> recolor everything; else drop extras & keep dom
        n=sum(cnt[c] for c in cnt)
        if n - cnt[dom] < n*0.3 and cnt[dom]>=1:
            for a,b in comp:
                out[a][b]=dom
        else:
            for a,b in comp:
                if grid[a][b]==dom: out[a][b]=dom
                else: out[a][b]=bg
    return out

