    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                col=grid[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        xx,yy=a+da,b+db
                        if 0<=xx<h and 0<=yy<w and not seen[xx][yy] and grid[xx][yy]==col:
                            seen[xx][yy]=True; st.append((xx,yy))
                out.append({'col':col,'cells':cells})
    return out
