def solve(inp, mode='nearest_centroid'):
    cnt=Counter(c for r in inp for c in r); bg=cnt.most_common(1)[0][0]
    Cs=comps_of(inp,bg); rects=[c for c in Cs if len(c['cells'])>1]
    singles=[c for c in Cs if len(c['cells'])==1]
    res=[r[:] for r in inp]
    def bbox(b):
        rs=[q[0] for q in b['cells']]; cs=[q[1] for q in b['cells']]
        return min(rs),max(rs),min(cs),max(cs)
    def dist(p,q): return abs(p[0]-q[0])+abs(p[1]-q[1])
    if mode=='nearest_centroid':
        def key(b):
            return (min(abs(p[0]-q[0])+abs(p[1]-q[1]) for q in b['cells']), len(b['cells']))
        # tiebreak by fewer cells -> closer rect gets the point? check demo results empirically. Use min cell count as secondary.
        for s in singles:
            p=s['cells'][0]
            bs=sorted(rects,key=lambda b:(min(dist(p,q) for q in b['cells']),len(b['cells'])))
            res[p[0]][p[1]]=bs[0]['col']
    elif mode=='bbox_or_adj':
        for s in singles:
            p=s['cells'][0]
            ins=[b for b in rects if bbox(b)[0]<=p[0]<=bbox(b)[2] and bbox(b)[1]<=p[1]<=bbox(b)[3]]
            if ins: res[p[0]][p[1]]=[b['col'] for b in ins][0]
            elif any(min(dist(p,q)==1 for q in b['cells']) for b in rects):
                # pick nearest among adjacent rects
                bs=[b for b in rects if any(dist(p,q)==1 for q in b['cells'])]
                res[p[0]][p[1]]=[b['col'] for b in bs][0]
            else:
                res[p[0]][p[1]]=bg
    else:
        raise
    for b in rects:
        r0,r1,c0,c1=bbox(b)
        for i in range(r0,r1+1):
            for j in range(c0,c1+1): res[i][j]=b['col']
    return res
